from melite_models import Model, Variant, Cell, LoraRow, Genre, Quant


class MeshRefine(Model):
    id = 'mesh_refine'
    genre = Genre.THREED
    label = 'UltraShape Mesh Refine'
    description = "Image-guided coarse-mesh refinement (UltraShape 1.0 DiT) — carves sharp limb separation + hard-surface edges into blobby TRELLIS output using the SAME guide image the mesh was generated from. The pre-rig cleanup step: run BEFORE SOMAX so proximity-based weight transfer can't glue arm vertices to torso bones."
    form = 'form_3d_mesh_refine'
    defaults = dict(
            box_v=1.0,
            mc_level=0.0,
            normalize_scale=0.99,
            num_latents=32768,
            num_sharp_points=204800,
            num_uniform_points=204800,
            preset='standard',
            dtype='bfloat16',
            low_vram=False,
            steps=50,
            guidance_scale=5.0,
            octree_resolution=384,
            num_chunks=8000,
            remove_bg=False,
            seed=42,
            file_format='glb',
            filename_prefix='ultrashape_refined',
        )
    # the CASCADE GATE (image-edit rework 2026-09-05) — this lane's
    # weight load is NOT a ComfyUI UNETLoader quant tier (audiocore
    # pack / native cpp / card-owned weightless flow / sam-or-npz
    # checkpoint). The cell ships NATIVE — the lane runs its single
    # native form; the lane's own engine owns whatever tier switching
    # the load has (NATIVE is the honest tier for "no UNETLoader
    # matrix").
    variants = (
        Variant(id='standard', label='Standard', route='mesh_refine', cells=(
            Cell(quant=Quant.NATIVE, label='Native', route='mesh_refine'),
        )),
    )


